FLAGS = {0x0002: "ACCOUNTDISABLE", 0x0010: "LOCKOUT", 0x0200: "NORMAL_ACCOUNT",
         0x10000: "DONT_EXPIRE_PASSWORD", 0x800000: "PASSWORD_EXPIRED"}

def decode(uac):
    return [name for bit, name in FLAGS.items() if uac & bit]

for v in (512, 514, 66048):
    print(v, hex(v), decode(v))
# 512 0x200 ['NORMAL_ACCOUNT']
# 514 0x202 ['ACCOUNTDISABLE', 'NORMAL_ACCOUNT']
# 66048 0x10200 ['NORMAL_ACCOUNT', 'DONT_EXPIRE_PASSWORD']
